INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(93306, 'ruRU', 'Молитва', '', 24330),
(93307, 'ruRU', '|cffADFF2F+$1i Сила артефакта|r', '', 24330),
(93310, 'ruRU', 'Пеплосерд...', '', 24330),
(93311, 'ruRU', '((Это будет короткая кат-сцена. Вы пытаетесь отдать Пеплосерд Тириону, но он отказывается.)) Нет... Я слишком искалечен, чтобы продолжать наследие Пеплосерда. Это бремя должно лечь на твои плечи, $p. С этого дня ты будешь владеть Пеплосердом против сил тьмы, где бы ты ни был нужен, защитник.', '', 24330),
(93312, 'ruRU', '((Это будет короткая кат-сцена. Вы пытаетесь отдать Пеплосерд Тириону, но он отказывается.)) Нет... Я слишком искалечен, чтобы продолжать наследие Пеплосерда. Это бремя должно лечь на твои плечи, $p. С этого дня ты будешь владеть Пеплосердом против сил тьмы, где бы ты ни был нужен, защитник.', '', 24330),
(93319, 'ruRU', 'Весть о твоих подвигах на Расколотом берегу уже разошлась. Пеплосерд... силы Легиона наверняка содрогнутся при твоём приближении.', '', 24330),
(93320, 'ruRU', 'Силы Пылающего Легиона бесчисленны. Если мы вообще хотим остановить их натиск, нужно пресечь его у истока — в Гробнице Саргераса.', '', 24330),
(93321, 'ruRU', 'Давным-давно титаны использовали могущественные орудия, именуемые Опорами Созидания, чтобы создать Азерот. Они — ключ к тому, чтобы навеки запечатать врата Легиона в наш мир.', '', 24330),
(93322, 'ruRU', 'Мы определили местонахождение одной из опор — Камня Приливов Голганнета. Он где-то на древнем острове Азсуна. Мне нужно, чтобы ты раздобыл его любой ценой.', '', 24330),
(93323, 'ruRU', 'Эйгвин тайно построила эту палату как своего рода защиту от Легиона. Мы должны раскрыть её секреты, чтобы суметь ею воспользоваться.', '', 24330),
(93324, 'ruRU', 'Зачем ты призвал меня сюда, бесёнок?', '', 24330),
(93325, 'ruRU', 'Прислужник! Рад, что ты смог прийти. Настало время заставить моего прежнего хозяина заплатить за нарушение договора. Готов встретиться с ним?', '', 24330),
(93326, 'ruRU', 'Начинай свой ритуал.', '', 24330),
(93327, 'ruRU', 'Ах... мой «бывший» хозяин. Прислужник! Убей его!', '', 24330),
(93328, 'ruRU', 'Ты проиграл, «хозяин»! И кто теперь хозяин?', '', 24330),
(93329, 'ruRU', 'Ты поплатишься за это предательство!', '', 24330),
(93330, 'ruRU', 'Конечно. Если Тирион зовёт, значит, это важно.', '', 24330),
(93331, 'ruRU', 'Следуй за мной, защитник. Позволь показать тебе Приют Последней Надежды и познакомить с Орденом Серебряной Длани.', '', 24330),
(93332, 'ruRU', 'Да! Да! Темноватые перья для темноватой цели!', '', 24330),
(93334, 'ruRU', 'Да! Да! Хорошо! Проклятая сила, текущая в этих рогах, бесценна для любого злого... эм... морально неоднозначного ритуала.', '', 24330),
(93335, 'ruRU', 'Отлично сработано, прислужник! По оливке на каждый мой палец.', '', 24330),
(93336, 'ruRU', 'Пожалуйста, присоединяйся. Я готов продолжить наш поход.', '', 24330),
(93337, 'ruRU', 'Дорогу малышу!', '', 24330),
(93338, 'ruRU', 'Встретимся на месте ритуала за наградой.', '', 24330),
(93340, 'ruRU', 'Верховный маг Кадгар, можешь направить один из этих порталов к часовне Последней Надежды?', '', 24330),
(93343, 'ruRU', 'Вперёд, братья! Возьмите свою судьбу в свои руки!', '', 24330),
(93352, 'ruRU', 'Больно...', '', 24330),
(93357, 'ruRU', 'Друиды Когтя, не дрогните! Мы должны отбить курганье логово!', '', 24330),
(93359, 'ruRU', 'Кенарий, мой наставник...$b$bКакая мерзкая сила могла подчинить его себе?', '', 24330),
(93361, 'ruRU', 'Я могу отвезти тебя обратно в Приют Последней Надежды, если нужно, герой.', '', 24330),
(93362, 'ruRU', 'Я хотел бы вернуться в Приют Последней Надежды.', '', 24330),
(93363, 'ruRU', 'Я не сплю, я не сплю...', '', 24330),
(93364, 'ruRU', 'Этот мир реален? Или именно сон — подлинная реальность?', '', 24330);
